import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.mob.*;import com.koios.GameService;
public final class MapDeathCheck {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 static void pulse(int n){for(int i=0;i<n;i++)GameService.getTaskScheduler().pulse();}
 public static void main(String[]args)throws Exception{PrototypeIntegrationCheck.loaded();
 for(int role=0;role<6;role++)try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob mob=f.mob(f.area(5,4,role),false);f.stand(CombatPresentationCheck.offset(mob.getLocation(),2,0));int index=mob.getIndex();long before=f.p.getArpgProgress().xp();mob.getFollowing().setFollow(f.p,com.koios.game.content.following.Following.FollowType.COMBAT);mob.hurt(999999,f.p);long xp=f.p.getArpgProgress().xp();int drops=GameService.getGroundItemManager().getPlayerItems(f.p).size();check(mob.isDead()&&mob.isVisible()&&!mob.isAttackable()&&mob.getHitpoints()==0,"Dead actor stays visible but cannot be targeted");check(mob.getCurrentAnimation()!=null&&mob.getCurrentAnimation().getId()==new int[]{5575,5491,836,5329,6576,5542}[role],"Cached role death animation requested");check(!mob.getFollowing().isFollowing()&&xp>before&&drops>0,"Death resets follow and immediately grants loot/XP");mob.hurt(999999,f.p);mob.death();check(f.p.getArpgProgress().xp()==xp&&GameService.getGroundItemManager().getPlayerItems(f.p).size()==drops,"Repeated hurt/death cannot repeat rewards");double life=CombatPresentationCheck.pool(f.p);for(int tick=0;tick<10;tick++){mob.update();MapRuns.tick(f.p);}check(CombatPresentationCheck.pool(f.p)==life,"Visible corpse cannot attack or follow");int duration=new int[]{9,6,10,6,7,6}[role];check(mob.collapseTicks()==duration,"Visible duration matches decoded cache animation cycles");pulse(duration-1);check(MobManager.mobs[index]==mob&&mob.isVisible(),"Corpse remains visible until its verified animation duration");pulse(1);check(MobManager.mobs[index]!=mob&&!mob.isVisible(),"Corpse removed after its verified animation duration");pulse(6);check(MobManager.mobs[index]!=mob&&f.p.getArpgProgress().xp()==xp,"No corpse respawn or delayed duplicate rewards");}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob boss=f.mob(f.area(6,4,-1),true);f.stand(CombatPresentationCheck.offset(boss.getLocation(),2,0));f.run.nextSlam=0;MapRuns.tick(f.p);check(f.run.slam!=null,"Boss fixture has active windup");boss.hurt(999999,f.p);check(f.run.complete&&f.run.slam==null&&boss.isVisible(),"Boss actual death completes map and cancels slam before visible collapse");for(int t=0;t<4;t++)MapRuns.tick(f.p);pulse(12);check(!boss.isVisible(),"Completed boss corpse eventually disappears");}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob corpse=f.mob(f.area(5,4,0),false);corpse.hurt(999999,f.p);int index=corpse.getIndex();MobManager.remove(corpse);Mob replacement=new Mob(73,f.run.spawn.copy()){};MobManager.spawn(replacement);check(replacement.getIndex()==index,"Replacement fixture reuses exact dead actor index");pulse(12);check(MobManager.mobs[index]==replacement,"Delayed corpse task cannot remove a reused world index");MobManager.remove(replacement);}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob corpse=f.mob(f.area(5,4,0),false);corpse.hurt(999999,f.p);MapRuns.cleanup(f.p);pulse(12);check(MobManager.mobs[corpse.getIndex()]!=corpse,"Instance cleanup safely cancels pending collapse");}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob mob=f.mob(f.area(5,4,0),false);f.stand(CombatPresentationCheck.offset(mob.getLocation(),2,0));mob.setDamage(new Damage(999999,DamageType.PHYSICAL,true),f.p);com.koios.game.model.player.update.MobUpdater updater=new com.koios.game.model.player.update.MobUpdater();com.koios.network.GamePacketBuilder block=new com.koios.network.GamePacketBuilder();updater.appendNPCUpdateBlock(mob,block,false);com.koios.network.GamePacket packet=block.toPacket();byte[] bytes=new byte[packet.getSize()];packet.getBuffer().getBytes(packet.getBuffer().readerIndex(),bytes);int flags=bytes[0]&255;check((flags&0x50)==0x50&&(flags&~0x70)==0,"Actual lethal update carries hit and death animation masks");int cursor=1;if((flags&0x10)!=0){check(((bytes[cursor]&255)|((bytes[cursor+1]&255)<<8))==5575,"Actual NPC update serializes verified collapse animation");cursor+=3;}if((flags&0x20)!=0)cursor+=2;cursor+=5;check(((128-bytes[cursor])&255)==0&&((-bytes[cursor+1])&255)>0,"Actual lethal NPC hit block serializes currentHP0 and positive maxHP");f.p.getLocalMobs().clear();f.p.getLocalMobs().add(mob);int before=((PrototypeIntegrationCheck.SessionStub)f.p.getSession()).packets.size();updater.update(f.p);check(f.p.getLocalMobs().contains(mob),"Production MobUpdater retains dead visible corpse in local NPC list");com.koios.network.GamePacket update=((PrototypeIntegrationCheck.SessionStub)f.p.getSession()).packets.get(before);byte[] wire=new byte[update.getSize()];update.getBuffer().getBytes(update.getBuffer().readerIndex(),wire);com.koios.client.stream.Stream stream=new com.koios.client.stream.Stream(wire);stream.initBitAccess();check(update.getOpcode()==65&&stream.readBits(8)==1&&stream.readBits(1)==1&&stream.readBits(2)==0,"Actual NPC update packet marks corpse as update-only, not removed");pulse(9);updater.update(f.p);check(!f.p.getLocalMobs().contains(mob),"Production MobUpdater removes corpse only after collapse finishes");}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){f.p.setAttribute("tutorial-stage",5);MapRuns.MapMob boss=f.mob(f.area(5,4,-1),true);long xp=f.p.getArpgProgress().xp();boss.hurt(999999,f.p);check(boss.getHitpoints()==1&&!boss.isDead()&&boss.isAttackable(),"Stage5 practice boss retains immortal one-HP floor");check(f.p.getArpgProgress().xp()==xp&&!f.run.complete,"Practice boss cannot grant premature death rewards");}
 try(CombatPresentationCheck.Fixture f=new CombatPresentationCheck.Fixture()){MapRuns.MapMob corpse=f.mob(f.area(5,4,0),false);corpse.hurt(999999,f.p);MapRuns.death(f.p);MapRuns.home(f.p);PrototypeIntegrationCheck.idle(f.p);pulse(9);check(!corpse.isVisible()&&MobManager.mobs[corpse.getIndex()]!=corpse,"Owner death/home during collapse safely finishes corpse removal");}
 System.out.println("Passed "+checks+" map-only death animation/lifecycle checks.");}
}
